6.1 Time Trend


Code
year_long &lt;- year_summary |&gt;
  mutate(year_num = as.integer(as.character(year))) |&gt;
  select(year, year_num, loss_ratio, claim_frequency, premium, incurred) |&gt;
  pivot_longer(c(loss_ratio, claim_frequency), names_to = "metric", values_to = "value") |&gt;
  mutate(metric = recode(metric, loss_ratio = "Loss ratio", claim_frequency = "Claim frequency"))

p_year_metrics &lt;- year_long |&gt;
  ggplot(aes(year_num, value, color = metric)) +
  geom_line(linewidth = 1.1) +
  geom_point(size = 3) +
  scale_x_continuous(breaks = unique(year_long$year_num)) +
  scale_y_continuous(labels = label_number(accuracy = 0.01)) +
  scale_color_manual(values = c("Loss ratio" = insurance_palette["brick"], "Claim frequency" = insurance_palette["teal"])) +
  labs(
    title = "Profitability and frequency trend",
    subtitle = "Claim frequency is expressed as claims per exposure year.",
    x = NULL,
    y = "Metric value"
  )

p_year_premium &lt;- year_summary |&gt;
  mutate(year_num = as.integer(as.character(year))) |&gt;
  select(year_num, premium, incurred) |&gt;
  pivot_longer(c(premium, incurred), names_to = "metric", values_to = "amount") |&gt;
  mutate(metric = recode(metric, premium = "Premium", incurred = "Incurred")) |&gt;
  ggplot(aes(factor(year_num), amount, fill = metric)) +
  geom_col(position = "dodge", width = 0.72) +
  scale_y_continuous(labels = label_dollar(prefix = "EUR ", scale_cut = cut_short_scale())) +
  scale_fill_manual(values = c("Premium" = insurance_palette["pine"], "Incurred" = insurance_palette["gold"])) +
  labs(
    title = "Premium and incurred by year",
    subtitle = "Both premium and incurred grew, but incurred grew faster in 2024.",
    x = NULL,
    y = "Amount"
  )

p_year_metrics + p_year_premium





Loss ratio deteriorated in 2024, even as premium and exposure expanded.




The portfolio expanded materially over the three-year period. Loss ratio remained near 66% in 2022 and 2023 but rose to 74.7% in 2024. This suggests that premium growth did not fully offset the growth in incurred loss.

